<?php
declare(strict_types=1);require_once __DIR__ . '/config/product_step12.php';
$error=null;$rows=[];$top=[];$months=[];$metrics=['active'=>0,'cancelled'=>0,'revenue'=>0.0,'vp'=>0.0,'paid'=>0.0,'outstanding'=>0.0,'profit'=>0.0,'profit_sales'=>0,'deferred'=>0];
try{$pdo=business_db();product_step12_ensure($pdo);$ctx=product_step12_context($pdo);$orgId=(int)$ctx['organization_id'];$rows=product_step12_sales_rows($pdo,$orgId,'all');
 foreach($rows as $r){if($r['sale_status']==='cancelled'){$metrics['cancelled']++;continue;}$metrics['active']++;$metrics['revenue']+=(float)$r['net_amount'];$metrics['vp']+=(float)$r['volume_points'];$metrics['paid']+=(float)$r['paid_amount'];$metrics['outstanding']+=max(0,(float)$r['net_amount']-(float)$r['paid_amount']);if($r['cost_status']==='complete'&&$r['profit_total']!==null){$metrics['profit']+=(float)$r['profit_total'];$metrics['profit_sales']++;}else{$metrics['deferred']++;}$key=substr((string)$r['order_date'],0,7);if(!isset($months[$key]))$months[$key]=['sales'=>0,'revenue'=>0.0,'vp'=>0.0,'profit'=>0.0,'profit_sales'=>0];$months[$key]['sales']++;$months[$key]['revenue']+=(float)$r['net_amount'];$months[$key]['vp']+=(float)$r['volume_points'];if($r['cost_status']==='complete'&&$r['profit_total']!==null){$months[$key]['profit']+=(float)$r['profit_total'];$months[$key]['profit_sales']++;}}
 krsort($months);
 $stmt=$pdo->prepare("SELECT poi.product_id,poi.stock_no,poi.product_name_snapshot,SUM(poi.quantity) qty,SUM(poi.line_price) revenue,SUM(poi.line_vp) vp FROM product_order_items poi JOIN product_sale_ledger l ON l.organization_id=poi.organization_id AND l.order_id=poi.order_id WHERE poi.organization_id=? AND l.sale_status='active' GROUP BY poi.product_id,poi.stock_no,poi.product_name_snapshot ORDER BY revenue DESC,qty DESC LIMIT 12");$stmt->execute([$orgId]);$top=$stmt->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
function psa_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function psa_num(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
?>
